method sort_third(l: seq<int>) returns (result: seq<int>)
    requires l != []
    ensures forall i :: 0 <= i < |l| ==> (i % 3 != 0 ==> result[i] == l[i]) && (i % 3 == 0 ==> result[i] in sorted_values)
    ensures |result| == |l|

    var sorted_values := new int[|l| / 3 + (if |l| % 3 != 0 then 1 else 0)];
    var count := 0;

    // Collect values at indices divisible by 3
    for i := 0 to |l| - 1
        invariant 0 <= i <= |l|
        invariant count == |{ j | j < i && j % 3 == 0 }|
    {
        if i % 3 == 0 {
            sorted_values[count] := l[i];
            count := count + 1;
        }
    }

    // Sort the collected values
    sorted(sorted_values);

    // Fill the result array
    for i := 0 to |l| - 1
        invariant 0 <= i <= |l|
    {
        if i % 3 == 0 {
            result[i] := sorted_values[i / 3];
        } else {
            result[i] := l[i];
        }
    }
}
